// Preparación editorial de actividades desde páginas revisadas visualmente.
// El contenido editable que utiliza la web queda en web/temas/t1.json ... t6.json.
const fs = require('node:fs');
const path = require('node:path');
const topics = [];
const book = (page,section) => ({document:'materiales/Libro GEP.pdf',pdfPage:page,printedPage:String(page-5),section});
const exam = (file,page,section) => ({document:`materiales/Examenes/${file}`,pdfPage:page,printedPage:'',section});
const pei = (page,section) => exam('wuolah-free-PEI-2024-25-Enunciado-gulag-free.pdf',page,section);
const ord = (page,section) => exam('wuolah-free-Ordinario-2023-24-Solucion-gulag-free.pdf',page,section);
function topic(number,title,conceptLabels,rows) {
  const t={id:`gep-t${number}`,number,title,status:'Actividades disponibles',conceptLabels,cards:[],cases:[],tests:[],map:null};
  for (const row of rows.trim().split('\n')) {
    const [id,concept,p,question,answer,explanation='']=row.split('|');
    t.cards.push({id:`gep-t${number}-${id}`,concepts:[concept],question,answer,explanation,sources:[book(Number(p),conceptLabels[concept])]});
  }
  topics.push(t);return t;
}
function scenario(t,id,concept,page,title,initial,change,constants,questions,options,solution,criteria,extraSources=[]) {
  t.cases.push({id:`${t.id}-caso-${id}`,concepts:[concept],title,kind:'Caso de elaboración propia · Predice y justifica',initial,change,constants,prompts:{elastic:questions[0],elongation:questions[1],reason:'Justifica las dos respuestas. Incluye el cálculo cuando corresponda.'},predictionOptions:{elastic:options[0],elongation:options[1]},solution,criteria,sources:[book(page,t.conceptLabels[concept]),...extraSources]});
}
function map(t,rows,blank1,blank2,solution) {
  const edges=rows.map(([concept,from,relation,to,page])=>({concepts:[concept],from,relation,to,group:t.conceptLabels[concept],sources:[book(page,t.conceptLabels[concept])]}));
  const blank=(spec)=>{const [edgeIndex,target,options,hint]=spec;return {edgeIndex,target,question:target==='to'?'Completa el concepto de destino':'Completa la relación',options,answer:edges[edgeIndex][target],hint};};
  t.map={id:`${t.id}-mapa`,title:`Conexiones · ${t.title}`,edges,blanks:{process:blank(blank1),relation:blank(blank2)},solution};
}
function test(t,id,concept,page,question,options,correct,explanation,extraSources=[]) {
  t.tests.push({id:`${t.id}-test-${id}`,concepts:[concept],question,options,correct,explanation,sources:[book(page,t.conceptLabels[concept]),...extraSources]});
}
const t1=topic(1,'La dirección empresarial',{
  direccion:'Niveles y función directiva',control:'Sistemas de control',estrategia:'Estrategia y crecimiento',funcional:'Benchmarking y reingeniería',corporativa:'Estrategia corporativa',competitiva:'Competencia, UEN y cadena de valor',internacional:'Dirección internacional'
},`
niveles|direccion|7|¿Cómo se diferencian alta dirección, dirección intermedia y dirección operativa?|La alta dirección define las estrategias globales; la intermedia dirige centros y departamentos; la operativa asigna tareas y supervisa el trabajo cotidiano.|La diferencia está en el alcance de las decisiones, no sólo en el nombre del cargo.
funciones|direccion|9|Reconstruye las cinco funciones del ciclo directivo.|Planificación, organización, ejecución, coordinación y control.|El control informa a la planificación del siguiente ciclo.
objetivo-plan|direccion|9|¿Qué diferencia hay entre un objetivo y un plan?|El objetivo expresa lo que se quiere conseguir; el plan establece los medios y las acciones para lograrlo.|El presupuesto traduce el plan a magnitudes económicas.
mision-vision|direccion|10|¿En qué se distinguen misión y visión?|La misión explica la razón de ser, actividad y mercado de la empresa; la visión describe la situación futura a la que aspira.|No son el mismo horizonte temporal.
formal-informal|direccion|10|¿Puede un organigrama describir toda la estructura real de una empresa?|No. Representa la estructura formal, pero la estructura real también incluye relaciones informales surgidas entre las personas.|La comunicación y los vínculos informales no desaparecen por existir normas.
coordinacion-control|direccion|11|¿Coordinar departamentos equivale a controlar su trabajo?|No. Coordinar alinea departamentos hacia objetivos comunes; controlar compara lo ejecutado con lo previsto e introduce correcciones.|Son funciones complementarias.
estatico-dinamico|direccion|8|¿Qué cambia al pasar del enfoque tradicional al actual de la competencia?|Se pasa de ciclos largos, necesidades estables y competidores definidos a ciclos más cortos, necesidades cambiantes y competencia global dinámica.|Una estrategia que supone estabilidad puede quedarse atrás.
ciclo-control|control|12|¿Qué pasos conectan un estándar con una acción correctiva?|Fijar estándares, medir desempeño, comparar resultados y determinar desviaciones; si no se cumplen los estándares, tomar medidas correctivas.|El principio de excepción concentra la atención en desviaciones importantes.
temporal-control|control|12|Distingue control preliminar, concurrente y de retroalimentación.|El preliminar actúa antes de iniciar la operación; el concurrente durante su ejecución; el de retroalimentación usa los resultados posteriores.|Distingue el momento del control de su mecanismo.
tres-controles|control|11|¿Qué mecanismos distinguen control burocrático, de mercado y de clan?|El burocrático usa normas y autoridad; el de mercado usa precios e información económica; el de clan usa valores compartidos y confianza.|No son tres nombres para una misma forma de supervisión.
auditorias|control|13|¿En qué se diferencian auditorías internas, externas y contables?|La interna evalúa periódicamente procesos de la propia compañía; la externa implica evaluación por otra organización; la contable verifica informes y estados contables.|Los controles presupuestarios comparan datos reales con presupuestados.
empowerment|control|14|¿Qué exige el empowerment además de delegar tareas?|Delegar poder y autoridad, proporcionar información y capacitación, y hacer al equipo responsable de su trabajo.|Delegar sin recursos ni capacidad de decisión deja incompleta la potenciación.
cinco-p|estrategia|15|¿Qué cinco perspectivas reúne el modelo de las 5P de Mintzberg?|Plan, estratagema o pauta de acción, patrón, posición y perspectiva.|La estratagema es una maniobra frente al rival; el patrón es consistencia en las acciones.
ansoff|estrategia|16|¿Cómo se construyen las cuatro opciones de Ansoff?|Productos actuales y mercados actuales: penetración; productos nuevos y mercados actuales: desarrollo de producto; productos actuales y mercados nuevos: desarrollo de mercado; ambos nuevos: diversificación.|La diversificación combina dos novedades y requiere gestionar más incertidumbre.
bm-tipos|funcional|19|Distingue benchmarking interno, competitivo, funcional y genérico.|Interno: entre unidades de la propia empresa; competitivo: con rivales directos; funcional: con líderes de otros sectores en una función común; genérico: sobre procesos comunes con independencia del sector.|Aprender de otros sectores puede aportar soluciones que no se usan en el propio.
bm-pasos|funcional|20|¿Cuáles son los cinco pasos del benchmarking?|Elegir actividades a emular, formar el equipo, identificar socios de comparación, recopilar y analizar información, ejecutar y controlar los resultados.|Comparar datos sin aplicar mejoras no completa el proceso.
bpr|funcional|21|¿Qué separa la reingeniería de una mejora incremental?|La reingeniería replantea y rediseña radicalmente procesos completos para obtener mejoras importantes; la mejora incremental ajusta el proceso existente.|La unidad de análisis pasa de departamentos aislados a procesos que crean valor.
corporativa|corporativa|22|¿Qué decide la estrategia corporativa que una estrategia funcional no abarca?|El alcance global de los negocios, las sinergias entre unidades y la asignación compartida de activos y recursos.|Se desarrolla en planos de liderazgo, económico y gerencial.
integracion|corporativa|23|¿Comprar un proveedor y crear una red propia de distribución son la misma integración vertical?|Ambas son integración vertical, pero comprar o asumir actividades previas es ascendente; asumir actividades posteriores es descendente.|La vertical se refiere a fases consecutivas de la cadena productiva.
diversificacion|corporativa|24|¿Cómo se distingue diversificación relacionada de no relacionada?|En la relacionada existe vínculo entre los negocios; en la no relacionada se entra en negocios sin esa relación.|La dimensión horizontal describe la variedad de negocios; la geográfica, su presencia espacial.
uen|competitiva|25|¿Qué cuatro aspectos se analizan para definir una UEN?|Misión, atractivo de la industria, posición competitiva y financiación.|La UEN debe poder sostenerse de forma autónoma y viable.
porter|competitiva|26|¿Qué cinco fuerzas describen el atractivo de una industria?|Rivalidad existente, poder de proveedores, poder de clientes, amenaza de nuevos competidores y amenaza de sustitutivos.|No confundas atractivo del sector con capacidades internas de una empresa.
valor|competitiva|27|¿Qué actividades primarias y de apoyo distingue la cadena de valor?|Primarias: logística interna, operaciones, logística externa, marketing y ventas, servicio posventa. Apoyo: infraestructura, recursos humanos, tecnología y abastecimiento.|Todas contribuyen a crear valor, aunque su relación con el producto sea distinta.
estrategias-genericas|competitiva|24|¿Qué diferencia una estrategia de costes de una de diferenciación y de una centrada?|Costes busca operar a menor coste; diferenciación ofrece atributos valorados distintos; la centrada aplica una ventaja a un segmento concreto.|El alcance del mercado y el tipo de ventaja son dimensiones distintas.
miles-snow|competitiva|29|Distingue prospectora, analizadora, defensora y reactiva.|La prospectora busca oportunidades nuevas; la analizadora combina negocio estable y nuevas oportunidades seleccionadas; la defensora protege una posición con eficiencia; la reactiva responde sin orientación consistente.|Son formas de adaptación al entorno.
bcg|competitiva|30|¿Qué variables y cuadrantes utiliza la matriz BCG?|Crecimiento del mercado y participación relativa. Alta-alta: estrella; alto crecimiento y baja participación: interrogación; bajo crecimiento y alta participación: vaca; baja-baja: perro.|La BCG no utiliza los ejes producto nuevo y mercado nuevo de Ansoff.
kotler|competitiva|30|¿Cómo se diferencian líder, retador, seguidor y especialista?|El líder tiene la mayor cuota; el retador ataca al líder; el seguidor rentabiliza una cuota menor; el especialista atiende un nicho reducido.|El libro relaciona estas posiciones con distintas acciones competitivas.
outsourcing-offshoring|internacional|32|¿Subcontratar implica necesariamente trasladar una actividad al extranjero?|No. Outsourcing implica externalizar; offshoring implica trasladar la actividad a otra zona geográfica. Pueden coincidir, pero no son equivalentes.|Distingue quién realiza el trabajo de dónde se realiza.
global-local|internacional|32|¿Cómo combinan integración global y respuesta local las estrategias internacionales?|Global: integración alta y respuesta local baja; multinacional: integración baja y respuesta local alta; transnacional: ambas altas; internacional: ambas bajas en el esquema del libro.|Los ejes responden a presiones diferentes.
entrada|internacional|32|¿Qué modalidades de entrada internacional compara el libro?|Exportación, licencias, franquicias, empresas conjuntas y subsidiarias de propiedad total.|Varían los costes, el control, el conocimiento local y los riesgos compartidos.
licencia-franquicia|internacional|32|¿Qué control puede perderse al conceder una licencia frente a una franquicia?|La tabla asocia las licencias con pérdida de control de la tecnología y las franquicias con pérdida de control de la calidad.|Es la comparación didáctica de la tabla del libro, no una recomendación universal.
intangibles|direccion|9|¿Por qué el conocimiento y el prestigio son recursos distintos de una máquina?|Son intangibles: no tienen la misma materialidad física y pueden desarrollarse mediante cooperación, aprendizaje y relaciones.|La función directiva también desarrolla estos recursos.
`);
scenario(t1,'ansoff','estrategia',16,'Una empresa abre otro mercado','Un fabricante vende el mismo sensor a compañías de su mercado habitual.','Comienza a vender ese sensor, sin modificarlo, a clientes de otro país.','El producto, la tecnología y el proceso de fabricación.', ['¿Qué estrategia de Ansoff aplica?','¿Qué variable de la matriz cambia?'],[['Desarrollo de mercado','Desarrollo de producto','Penetración de mercado'],['El mercado','El producto','Ambas variables']], 'Es desarrollo de mercado: conserva el producto y accede a un mercado nuevo. No es diversificación, porque no se introduce simultáneamente un producto nuevo.', ['Identificas las dos variables de Ansoff.','Distingues desarrollo de mercado de diversificación.']);
scenario(t1,'control','control',12,'Detectar un desvío mientras se produce','Una línea tiene un objetivo diario de producción.','El supervisor observa retrasos durante el turno y reajusta las tareas antes de terminarlo.','El objetivo y el procedimiento de medición.', ['¿Qué enfoque temporal de control aparece?','¿Qué función compara resultados con el objetivo?'],[['Concurrente','Preliminar','De retroalimentación'],['Control','Planificación','Organización']], 'Es control concurrente porque se realiza durante la ejecución. La comparación con el estándar pertenece al control; el ajuste evita esperar al cierre del turno.', ['Justificas el momento en que se interviene.','Relacionas medición, estándar y corrección.'],[pei(1,'Preguntas 1–3: funciones directivas')]);
scenario(t1,'integracion','corporativa',23,'Fabricar una materia prima','Una empresa compra una materia prima a un proveedor independiente.','Adquiere al proveedor y pasa a gestionar directamente esa actividad.','El producto final y los clientes.', ['¿Qué dimensión estratégica cambia?','¿Cuál es la orientación de la integración?'],[['Vertical','Horizontal','Geográfica'],['Ascendente','Descendente','No hay integración']], 'Es integración vertical ascendente: se incorpora una etapa previa de la cadena productiva. No se entra necesariamente en un nuevo mercado final ni en otra región.', ['Sitúas la actividad antes del proceso principal.','No confundes integración con diversificación.']);
scenario(t1,'matrices','competitiva',30,'Ansoff no determina la BCG','Una unidad lanza un producto nuevo en un mercado nuevo.','Se pide asignar un cuadrante de BCG usando sólo ese dato.','No se conocen ni crecimiento del mercado ni participación relativa.', ['¿Qué estrategia de Ansoff se identifica?','¿Puede determinarse un cuadrante BCG?'],[['Diversificación','Penetración','Desarrollo de producto'],['No, faltan los dos ejes de BCG','Sí, siempre interrogación','Sí, siempre estrella']], 'Ansoff permite identificar diversificación. BCG requiere crecimiento y participación relativa: la novedad del producto y mercado no basta. Una pregunta que iguala ambas matrices sin esos datos es ambigua.', ['Nombras los ejes distintos de las matrices.','Explicas qué información falta.'],[pei(3,'Pregunta 11: comparación Ansoff–BCG; ambigüedad de datos')]);
map(t1,[['direccion','Objetivo','se concreta mediante','Plan',9],['control','Control','compara resultados con','Estándares',12],['estrategia','Producto actual + mercado nuevo','define','Desarrollo de mercado',17],['funcional','Benchmarking','aprende mediante','Comparación con buenas prácticas',18],['corporativa','Integración ascendente','incorpora','Actividades previas',23],['competitiva','Cinco fuerzas','evalúan','Atractivo de la industria',26],['competitiva','Cadena de valor','analiza','Actividades creadoras de valor',27],['internacional','Transnacional','combina','Integración global y respuesta local altas',32]],[0,'to',['Plan','Resultado de explotación','Cuota de mercado'],'El objetivo es el fin; busca el medio.'],[1,'relation',['compara resultados con','sustituye por completo','impide medir'],'Necesita un patrón de desempeño esperado.'],'La dirección convierte objetivos en planes y comprueba su cumplimiento. Las decisiones sobre alcance, ventaja competitiva e internacionalización se apoyan en herramientas con ejes diferentes.');
