const t5=topic(5,'Gestión de marketing',{marketing:'Marketing y valor',plan:'Plan e investigación',mezcla:'Las cuatro P',estrategia:'Marketing estratégico',servicio:'Comunicación y posventa'},`
definicion|marketing|111|¿Por qué marketing es más que publicidad?|Orienta intercambios y decisiones de la organización hacia satisfacer necesidades del cliente de forma compatible con sus objetivos.|La publicidad es sólo una herramienta de comunicación.
valor|marketing|112|¿Cómo se relacionan valor percibido y satisfacción?|El valor contrasta beneficios con costes o sacrificios; la satisfacción compara experiencia con expectativas.|El precio monetario no representa todos los sacrificios.
demanda|marketing|112|¿Gestionar demanda siempre significa aumentarla?|No: puede requerir aumentarla, reducirla o regular su distribución temporal.|La capacidad y los objetivos condicionan la actuación.
plan|plan|113|¿Qué componentes conecta un plan de marketing?|Situación, objetivos, estrategia, acciones, presupuesto, calendario, responsables y control.|Una lista de acciones sin objetivos ni seguimiento no es un plan completo.
investigacion|plan|115|Distingue preguntar, experimentar y observar registros en investigación comercial.|Encuestas recogen lo que se dice; pruebas de mercado observan lo que se hace en una situación; registros históricos muestran lo que se hizo.|Intención declarada y compra efectiva pueden diferir.
cuatro-p|mezcla|116|¿Cuáles son las cuatro P del marketing mix?|Producto, precio, distribución y promoción o comunicación.|Deben coordinarse entre sí y con el mercado objetivo.
producto|mezcla|117|¿Un producto tiene que ser tangible?|No: también puede ser un servicio u oferta intangible.|La clasificación comercial distingue conveniencia, comparación y especialidad.
ciclo|mezcla|117|¿Qué etapas tiene el ciclo de vida del producto?|Introducción, crecimiento, madurez y declive.|Es un esquema para analizar decisiones, no un calendario fijo de todos los productos.
precio|mezcla|118|¿Qué tres referencias orientan la fijación del precio?|Costes, competencia y demanda o valor percibido.|Elegir sólo una referencia puede ignorar restricciones importantes.
lanzamiento|mezcla|118|Distingue penetración de descremación en precios de lanzamiento.|Penetración busca entrada con precio relativamente bajo; descremación inicia con precio alto para captar segmentos dispuestos a pagar más.|Su conveniencia depende de demanda, competencia y costes.
distribucion|mezcla|119|¿Qué aporta la distribución además de transportar?|Almacenamiento, información, financiación y organización de intercambios; los intermediarios pueden reducir contactos necesarios.|Mayorista y minorista ocupan posiciones distintas en el canal.
promocion|servicio|119|Distingue publicidad, promoción de ventas y venta personal.|Publicidad: comunicación pagada e impersonal; promoción: incentivos normalmente temporales; venta personal: interacción directa con el comprador.|Publicity se refiere a difusión no pagada en este esquema.
posventa|servicio|120|¿Qué aporta gestionar reclamaciones al marketing?|Permite recuperar confianza, resolver problemas y obtener información para mejorar.|Escucha, empatía, evidencia, respuesta y seguimiento son parte del proceso.
dafo|estrategia|122|Clasifica fortalezas, debilidades, oportunidades y amenazas.|Fortalezas y debilidades son internas; oportunidades y amenazas proceden del entorno.|Una misma situación se clasifica desde la perspectiva de la empresa analizada.
segmentacion|estrategia|123|¿Qué convierte un segmento en un objetivo utilizable?|Información para conocerlo, acceso, tamaño suficiente, diferenciación y posibilidad de defender la posición.|Agrupar clientes no basta si no se puede actuar sobre el grupo.
niveles|estrategia|123|Distingue marketing de masas, segmentos, nichos e individual.|Aumentan el detalle de adaptación desde una oferta general hasta una oferta para una persona o cliente concreto.|Nicho es un grupo reducido y definido, no sinónimo de toda segmentación.
posicionamiento|estrategia|124|¿Qué significa posicionamiento?|El lugar que ocupa la oferta en la percepción del público frente a alternativas.|No describe la ubicación física del almacén.
aeroespacial|servicio|125|¿Qué rasgos destaca el libro para el marketing aeroespacial?|Peso de requisitos técnicos, relaciones industriales, ferias y servicios de soporte posventa complejos.|La oferta debe conectar valor para el cliente con capacidad de cumplimiento.
`);
scenario(t5,'dafo','estrategia',122,'Un cambio en el entorno','Un fabricante tiene un equipo técnico propio muy especializado.','Un nuevo competidor entra en su mercado.','Se analiza desde la perspectiva del fabricante.', ['¿Cómo clasificar el equipo especializado?','¿Cómo clasificar la entrada del rival?'],[['Fortaleza interna','Oportunidad externa','Amenaza externa'],['Amenaza externa','Debilidad interna','Fortaleza interna']], 'La capacidad técnica propia es una fortaleza interna; la entrada de un competidor es una amenaza del entorno. DAFO separa origen interno y externo.', ['Mantienes la perspectiva de la empresa.','No confundes un problema externo con una debilidad propia.']);
scenario(t5,'precio','mezcla',118,'Precio de lanzamiento','Un producto nuevo se ofrece inicialmente a un segmento dispuesto a pagar mucho.','Más adelante se prevé bajar el precio para ampliar compradores.','No se está describiendo el coste de fabricación.', ['¿Qué política de lanzamiento encaja?','¿Qué dato conviene comprobar?'],[['Descremación','Penetración','Precio siempre nulo'],['Disposición a pagar y reacción competitiva','Sólo color del envase','Sólo número de trabajadores']], 'Es descremación: captar primero segmentos con mayor disposición a pagar. Hay que comprobar que demanda y competencia permiten la política.', ['Relacionas precio inicial alto con la estrategia.','Evitas presentarla como garantía de éxito.']);
scenario(t5,'encuesta','plan',115,'Intención de compra','Una encuesta muestra mucho interés en un servicio.','Un piloto mide cuántos clientes lo contratan realmente.','La población objetivo es comparable.', ['¿Qué mide la encuesta?','¿Qué añade el piloto?'],[['Declaración de intención','Venta efectiva garantizada','Beneficio neto'],['Conducta observable en prueba','Garantía de ventas futuras','Ausencia de incertidumbre']], 'La encuesta recoge opiniones; el piloto observa una conducta bajo condiciones concretas. Ninguno elimina incertidumbre y se deben revisar sesgos y representatividad.', ['Distingues declaración y conducta.','No generalizas automáticamente el piloto.']);
map(t5,[['marketing','Marketing','parte de','Necesidades del cliente',111],['marketing','Satisfacción','compara experiencia con','Expectativas',112],['plan','Plan','vincula','Objetivos, acciones y control',113],['mezcla','Marketing mix','coordina','Producto, precio, distribución y promoción',116],['servicio','Posventa','contribuye a','Fidelización y aprendizaje',120],['estrategia','DAFO','separa','Interior y entorno',122],['estrategia','Segmentación','identifica','Grupos de necesidades similares',123],['estrategia','Posicionamiento','ocurre en','Percepción del público',124]],[3,'to',['Producto, precio, distribución y promoción','Sólo publicidad','Sólo producción y coste'],'Son las cuatro P.'],[7,'relation',['ocurre en','almacena físicamente','elimina'],'Piensa en cómo percibe la oferta el comprador.'],'La estrategia define a quién servir y qué valor ofrecer; el mix y la posventa llevan esa propuesta a la práctica.');
