scenario(t6,'herramienta','herramientas',134,'Elegir una herramienta','Se registran cien incidencias clasificadas por tipo.','Se desea priorizar las categorías que más contribuyen al total.','Se conocen las frecuencias por categoría.', ['¿Qué herramienta elegir?','¿Qué no se puede presuponer?'],[['Pareto','Diagrama de dispersión sin pares','Organigrama'],['Que siempre se cumple exactamente 80/20','Que hay categorías','Que las frecuencias se pueden sumar']], 'Pareto ordena categorías por contribución y permite observar acumulados. Los datos determinarán qué proporción explica el mayor volumen; no se impone 80/20.', ['Relacionas herramienta y objetivo.','Usas frecuencias, no una proporción prefijada.']);
scenario(t6,'pdca','concepto',128,'Un piloto y sus resultados','Se planifica una mejora y se prueba en una línea.','Se comparan tasas de defectos antes y después frente al objetivo.','El método de medición es comparable.', ['¿Qué fase se realiza al comparar?','¿Qué viene si la mejora se confirma?'],[['Check: comprobar','Do: ejecutar','Plan: formular objetivos'],['Act: consolidar y seguir mejorando','Abandonar medición','Borrar criterios']], 'Comparar evidencia con el objetivo es Check. Después se actúa: se consolida lo que funciona o se corrige lo que falla, alimentando otro ciclo.', ['No confundes prueba con evaluación.','Cierras el ciclo con actuación.']);
scenario(t6,'sigma','excelencia',142,'Oportunidades y unidades','Una pieza tiene cinco oportunidades de defecto. Se evalúan mil piezas.','Se observan diez defectos y se quiere calcular DPMO.','Cada pieza aporta las mismas cinco oportunidades.', ['¿Cuántas oportunidades se evaluaron?','¿Cuál es el DPMO?'],[['5.000','1.000','10.000'],['2.000','10.000','3,4']], 'DPMO = 10/(1.000×5)×1.000.000 = 2.000. No se divide sólo por piezas y tampoco se presupone el valor convencional de Six Sigma.', ['Distingues unidad de oportunidad.','Incluyes el factor por millón.']);
map(t6,[['concepto','PDCA','conecta','Planificar, hacer, comprobar y actuar',128],['autores','Juran','propone','Planificar, controlar y mejorar',131],['herramientas','Pareto','ayuda a','Priorizar categorías',134],['herramientas','Ishikawa','organiza','Posibles causas',134],['sistema','SGC','integra','Procesos y responsabilidades',136],['sistema','Decisiones de calidad','se apoyan en','Evidencia',138],['excelencia','DMAIC','termina con','Controlar la mejora',143],['aeroespacial','Familia 9100','añade','Requisitos aeroespaciales',146]],[2,'to',['Priorizar categorías','Probar automáticamente causalidad','Obligar a un 80/20 exacto'],'Ordena las contribuciones al problema.'],[5,'relation',['se apoyan en','prescinden de','sustituyen'],'Piensa en uno de los siete principios.'],'La calidad conecta requisitos, procesos, datos y mejora. La certificación y los modelos de excelencia tienen propósitos distintos.');
test(t6,'pdca','concepto',128,'Comparar los resultados con el objetivo es…',['Check','Do','Plan','Ninguna fase'],0,'La comprobación precede a la actuación de consolidación o corrección.');
test(t6,'juran','autores',131,'La trilogía de Juran incluye…',['Sólo inspección','Planificación, control y mejora','Sólo costes','Publicidad y venta'],1,'Las tres funciones se complementan.');
test(t6,'causa','herramientas',134,'Para organizar posibles causas de un defecto usarías…',['Balance','Matriz BCG','Ishikawa','Ansoff'],2,'El diagrama causa-efecto estructura hipótesis de causas.');
test(t6,'sigma','excelencia',142,'DPMO usa como denominador…',['Sólo ingresos','Sólo días','Siempre unidades sin ajustes','Número de oportunidades de defecto'],3,'Las oportunidades por unidad deben estar definidas.');
test(t6,'dmaic','excelencia',143,'DMAIC acaba con…',['Controlar','Crear publicidad','Cerrar la empresa','Repetir sin medir'],0,'Busca mantener la mejora.');
test(t6,'familia','aeroespacial',146,'En el esquema del libro, 9110 corresponde a…',['Distribución','Mantenimiento','Sólo marketing','Contabilidad'],1,'9100 se relaciona con diseño y fabricación; 9120 con distribución.');
